import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';


export type CartoonEarthProps = Record<string, any>;

// Shared path generation for the procedural landmasses
const MapShapesLayer = ({ color, cutoutColor }: { color: string; cutoutColor?: string }) => {
  return (
    <g fill={color} strokeLinejoin="round" strokeWidth={10} stroke={color}>
      {/* Americas */}
      <path d="M -700 50 C -600 30, -500 150, -450 250 C -400 400, -500 550, -450 650 C -400 750, -550 800, -600 700 C -650 550, -550 450, -580 300 C -620 150, -800 100, -700 50 Z" />
      <path d="M -300 30 C -250 10, -200 60, -220 110 C -250 160, -350 110, -300 30 Z" /> {/* Greenland */}
      <path d="M -350 400 C -320 380, -300 420, -330 430 Z" /> {/* Caribbean Islands */}
      <path d="M -280 430 C -250 410, -220 460, -260 470 Z" />

      {/* Europe/Africa */}
      <path d="M -50 50 C 150 20, 200 150, 250 200 C 350 220, 450 180, 550 250 C 600 350, 500 450, 400 500 C 350 650, 200 800, 100 750 C 0 700, -50 550, 50 450 C 100 400, 50 350, -20 300 C -80 250, -150 150, -50 50 Z" />
      
      {/* Mediterranean Sea Cutout */}
      {cutoutColor && (
        <path
          d="M 50 220 C 120 220, 150 250, 120 290 C 80 270, 40 250, 50 220 Z"
          fill={cutoutColor}
          stroke={cutoutColor}
          strokeWidth={4}
        />
      )}

      {/* Asia / Oceania */}
      <path d="M 600 100 C 700 50, 850 150, 950 200 C 1050 300, 900 450, 850 500 C 800 600, 700 650, 600 550 C 650 450, 550 350, 500 250 C 550 200, 550 150, 600 100 Z" />
      <path d="M 750 600 C 850 580, 950 650, 900 750 C 850 850, 750 800, 700 700 C 650 600, 700 620, 750 600 Z" /> {/* Australia */}
      <path d="M 900 650 C 920 630, 950 670, 930 690 Z" /> {/* Indonesian Islands */}
      <path d="M 850 620 C 880 600, 900 640, 870 660 Z" />
    </g>
  );
};

const CartoonEarth: React.FC<CartoonEarthProps> = ({
  backgroundColor = "#071736",
  transparentBackground = false,
  durationInSeconds = 8,
  oceanColor = "#228be6",
  oceanEdgeColor = "#1864ab",
  landColor = "#8ce94a",
  landRimColor = "#5c9424",
  rotationSpeed = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Base canvas scale factor
  const s = Math.min(width, height) / 1080;

  // Background parsing
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout parameters
  // R is very large to create a gentle curve exactly like the reference image
  const R = width * 0.9;
  const cx = width / 2;
  
  // The planet targets a Y position where its top reaches slightly below the middle of the screen
  const targetCy = height * 0.6 + R;
  
  // Entrance animation: starts fully off-screen (bottom) and gently rises
  const startCy = height * 1.6 + R;
  const entranceDuration = fps * 2;
  
  const cy = interpolate(
    frame,
    [0, entranceDuration],
    [startCy, targetCy],
    {
      easing: Easing.out(Easing.cubic),
      extrapolateRight: "clamp",
    }
  );

  // Rotation animation (simulated by horizontal panning of the map surface)
  const panX = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [0, -width * 0.15 * rotationSpeed]
  );

  // Scale map coordinates to fit the giant planet surface beautifully
  const mapScale = R / 1100;
  // Rim thickness for the 3D continent edge, responsive to canvas size
  const rimOffset = 20 * (s / mapScale); 

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* Optional subtle space gradient if background is not transparent */}
      {!transparentBackground && (
        <div 
          style={{ 
            position: "absolute", 
            inset: 0, 
            background: "radial-gradient(circle at 50% 0%, rgba(255,255,255,0.05) 0%, rgba(0,0,0,0.3) 100%)",
            transition: "none"
          }} 
        />
      )}

      <svg width="100%" height="100%" style={{ overflow: "visible", transition: "none" }}>
        <defs>
          <clipPath id="globe-clip">
            <circle cx={cx} cy={cy} r={R} />
          </clipPath>
          
          <radialGradient id="ocean-grad" cx="50%" cy="50%" r="50%">
            <stop offset="60%" stopColor={oceanColor} />
            <stop offset="100%" stopColor={oceanEdgeColor} />
          </radialGradient>

          <radialGradient id="globe-shadow" cx="50%" cy="20%" r="80%">
            <stop offset="50%" stopColor="rgba(0,0,0,0)" />
            <stop offset="85%" stopColor="rgba(0,0,30,0.15)" />
            <stop offset="100%" stopColor="rgba(0,0,30,0.4)" />
          </radialGradient>
        </defs>

        <g clipPath="url(#globe-clip)" style={{ transition: "none" }}>
          {/* Base Ocean */}
          <circle cx={cx} cy={cy} r={R} fill="url(#ocean-grad)" style={{ transition: "none" }} />

          {/* Panning Map Layer */}
          <g transform={`translate(${panX}, 0)`} style={{ transition: "none" }}>
            {/* Coordinate mapper: local (0,0) is pinned to the top vertex of the globe */}
            <g transform={`translate(${cx}, ${cy - R}) scale(${mapScale})`} style={{ transition: "none" }}>
              {/* Loop the map multiple times to ensure continuous panning without visible edges */}
              {[-1, 0, 1, 2, 3].map((offset) => (
                <g key={offset} transform={`translate(${offset * 2000}, 0)`} style={{ transition: "none" }}>
                  {/* 3D Rim (Bottom Shadow Layer) */}
                  <g transform={`translate(0, ${rimOffset})`} style={{ transition: "none" }}>
                    <MapShapesLayer color={landRimColor} cutoutColor={oceanColor} />
                  </g>
                  
                  {/* Top Landmass Layer */}
                  <MapShapesLayer color={landColor} cutoutColor={oceanColor} />
                </g>
              ))}
            </g>
          </g>

          {/* Atmosphere Volume Shadow (Simulates 3D sphere lighting on top of everything) */}
          <circle cx={cx} cy={cy} r={R} fill="url(#globe-shadow)" style={{ transition: "none" }} />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default CartoonEarth;